-- 能力字典加图标列：存 SVG 原文（24×24 stroke 线稿、currentColor 跟随前景色）。
-- admin 与 console 展示/描述模型能力时统一用图标 + 悬浮文字（文案 admin 取 display_name/description，console 走 i18n）。
-- 空串表示未配置，前端回退为通用勾选图标；新建能力时 admin 表单要求必填。
ALTER TABLE public.capability_keys
    ADD COLUMN icon_svg text DEFAULT ''::text NOT NULL;

COMMENT ON COLUMN public.capability_keys.icon_svg IS '能力图标 SVG 原文（24×24 stroke、currentColor）；空串=未配置，前端回退通用图标。';

-- 33 个既有能力逐一配互不重复的图标（取自 lucide 线稿）。
-- 仅在 icon_svg 仍为空时写入，不覆盖运维已自定义的图标（重复执行安全）。
UPDATE public.capability_keys SET icon_svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v16"/><path d="M4 7V5a1 1 0 0 1 1-1h14a1 1 0 0 1 1 1v2"/><path d="M9 20h6"/></svg>' WHERE key = 'text.input' AND icon_svg = '';
